import Image from 'next/image'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type RelatedProductItem = {
  id: string
  title: string
  category: string
  href: string
  image?: { src: string; alt: string }
}

export type RelatedProductsProps = {
  products: readonly RelatedProductItem[]
  title?: string
  eyebrow?: string
  variant?: 'cards' | 'list'
  tone?: AccentTone
  className?: string
}

const gridLines: Record<AccentTone, string> = {
  glow: 'border-[#493849] bg-[#493849]',
  industrial: 'border-slate-200 bg-slate-200',
  'industrial-dark': 'border-white/10 bg-white/10',
}

/** Produtos relacionados em cards com imagem ou em lista editorial com seta. */
export function RelatedProducts({
  products,
  title,
  eyebrow = 'Continue explorando',
  variant = 'cards',
  tone = 'glow',
  className,
}: RelatedProductsProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'

  if (!products.length) return null

  return (
    <section className={cn(t.section, className)}>
      <div className="container py-14 lg:py-16">
        {title ? (
          <EyebrowHeading tone={tone} eyebrow={eyebrow} title={title} className="mb-10 lg:mb-12" />
        ) : (
          <div className="mb-8 flex items-center gap-3">
            <span className={cn('h-px w-8', t.line)} aria-hidden />
            <span className={cn('text-[0.65rem] uppercase tracking-[0.28em]', t.accent)}>
              {eyebrow}
            </span>
          </div>
        )}

        {variant === 'cards' ? (
          <div className={cn('grid grid-cols-1 gap-px border md:grid-cols-3', gridLines[tone])}>
            {products.map((product) => (
              <Link
                key={product.id}
                href={product.href}
                className={cn('group flex flex-col', t.panel, t.focus)}
              >
                {product.image ? (
                  <div className="relative h-48 overflow-hidden">
                    <Image
                      src={product.image.src}
                      alt={product.image.alt}
                      fill
                      sizes="(max-width: 768px) 100vw, 33vw"
                      className="object-cover transition-transform duration-700 group-hover:scale-105"
                    />
                  </div>
                ) : null}
                <div className="p-6">
                  <p className={cn('text-[0.65rem] uppercase tracking-[0.2em]', t.accent)}>
                    {product.category}
                  </p>
                  <h3
                    className={cn(
                      'mt-2 text-lg font-semibold tracking-wide',
                      !isGlow && 'uppercase',
                      t.strong,
                    )}
                  >
                    {product.title}
                  </h3>
                </div>
              </Link>
            ))}
          </div>
        ) : (
          <ul className={cn('divide-y border-y', t.divide, t.border)}>
            {products.map((product) => (
              <li key={product.id}>
                <Link
                  href={product.href}
                  className={cn(
                    'group flex items-center justify-between gap-6 py-6 transition-colors',
                    t.focus,
                  )}
                >
                  <div>
                    <p className={cn('text-[0.65rem] uppercase tracking-[0.2em]', t.accent)}>
                      {product.category}
                    </p>
                    <h3
                      className={cn(
                        'mt-1 text-xl font-semibold tracking-wide transition-colors',
                        !isGlow && 'uppercase',
                        t.strong,
                        isGlow ? 'group-hover:text-[#ffb0eb]' : 'group-hover:text-amber-600',
                      )}
                    >
                      {product.title}
                    </h3>
                  </div>
                  <ArrowUpRight
                    className={cn(
                      'h-5 w-5 shrink-0 transition-transform group-hover:rotate-45',
                      t.muted,
                    )}
                    aria-hidden
                  />
                </Link>
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'

import { cn } from '@/lib/utils'

import { getAccentTone, type AccentTone } from './accentTones'

export type EyebrowHeadingProps = {
  title: ReactNode
  eyebrow?: ReactNode
  description?: ReactNode
  tone?: AccentTone
  align?: 'left' | 'center'
  layout?: 'stacked' | 'split'
  size?: 'md' | 'lg'
  titleAs?: 'h1' | 'h2' | 'h3'
  action?: ReactNode
  className?: string
}

const titleSizes = {
  md: 'text-3xl leading-[1.15] sm:text-4xl lg:text-[2.5rem]',
  lg: 'text-3xl leading-[1.12] sm:text-4xl md:text-5xl lg:text-[3.25rem]',
}

/** Cabeçalho de seção com linha de destaque, título temático e descrição opcional ao lado. */
export function EyebrowHeading({
  title,
  eyebrow,
  description,
  tone = 'glow',
  align = 'left',
  layout = 'stacked',
  size = 'md',
  titleAs: Title = 'h2',
  action,
  className,
}: EyebrowHeadingProps) {
  const t = getAccentTone(tone)
  const centered = align === 'center'
  const split = layout === 'split' && !centered

  const line = <span className={cn('h-px w-8 shrink-0', t.line)} aria-hidden />

  return (
    <div
      className={cn(
        split && 'flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between',
        centered && 'mx-auto max-w-3xl text-center',
        className,
      )}
    >
      <div className={cn(split ? 'max-w-2xl' : centered ? '' : 'max-w-3xl')}>
        {eyebrow ? (
          <div className={cn('mb-4 flex items-center gap-3', centered && 'justify-center')}>
            {line}
            <span
              className={cn('text-[0.65rem] font-medium uppercase tracking-[0.28em]', t.accent)}
            >
              {eyebrow}
            </span>
            {centered ? line : null}
          </div>
        ) : null}
        <Title className={cn(t.heading, titleSizes[size], centered && 'mx-auto')}>{title}</Title>
        {!split && description ? (
          <p
            className={cn(
              'mt-5 max-w-2xl text-base leading-relaxed md:text-lg',
              t.body,
              centered && 'mx-auto',
            )}
          >
            {description}
          </p>
        ) : null}
        {!split && action ? (
          <div className={cn('mt-8 flex flex-wrap gap-3', centered && 'justify-center')}>
            {action}
          </div>
        ) : null}
      </div>
      {split && (description || action) ? (
        <div className="max-w-md space-y-5">
          {description ? (
            <p className={cn('text-sm leading-relaxed lg:text-base', t.body)}>{description}</p>
          ) : null}
          {action}
        </div>
      ) : null}
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
